-- Eighth private chapter: Throne of Seal fanart; additive, preserves visibility and accounts.
insert into jj_collect.catalog(id,data) values('nu-211','{"id": "nu-211", "number": 211, "name_es": "Aprendiz de la luz", "name_en": "Apprentice of Light", "character": "jesus", "theme": "fantasia", "tags": ["throne-of-seal"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Me ilusiona empezar una aventura contigo, aunque todavía tengamos mucho que aprender.", "dedication_en": "I love starting an adventure with you, even when we still have so much to learn.", "art": 0, "collection": "octavo-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-212','{"id": "nu-212", "number": 212, "name_es": "Primer paso en las sombras", "name_en": "First Step in Shadow", "character": "julisa", "theme": "fantasia", "tags": ["throne-of-seal"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "En esta historia imaginé tu valentía a tu manera, sin pedirte que escondas quién eres.", "dedication_en": "In this story I imagined your courage in your own way, without asking you to hide who you are.", "art": 1, "collection": "octavo-universo"}'::jsonb) on conflict(id) do nothing;
insert into jj_collect.catalog(id,data) values('nu-213','{"id": "nu-213", "number": 213, "name_es": "La puerta de nuestra aventura", "name_en": "The Gate of Our Adventure", "character": "duo", "theme": "fantasia", "tags": ["throne-of-seal"], "rarity": 0, "sell": 4, "scrap": 1, "craft": 8, "dedication_es": "Si cruzamos esta puerta, quiero escuchar también qué camino te gustaría explorar.", "dedication_en": "If we cross this gate, I want to hear which path you would love to explore too.", "art": 2, "collection": "octavo-universo"}'::jsonb) on conflict(id) do nothing;
